/**
 * Generated importer for Anak Kads rows from CSV/XLSX.
 */
class AnakKadImporter extends Importer
{
    protected static ?string $model = AnakKad::class;

    /**
     * Mappable import columns with type casts and rules.
     * @return  array  ImportColumn definitions.
     */
    public static function getColumns(): array
    {
        return [
            ImportColumn::make('id')
                ->label('ID')
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['nullable', 'integer'])
                ->examples(['1', '2'])
                ->exampleHeader('ID'),

            ImportColumn::make('tajuk_kad')
                ->label('Card Title')
                ->requiredMapping()
                ->ignoreBlankState()
                ->rules(['required', 'max:255'])
                ->examples(['Sample Card Title 1', 'Sample Card Title 2'])
                ->exampleHeader('Card Title'),

            ImportColumn::make('induk')
                ->label('nama_induk')
                ->relationship(resolveUsing: ['nama_induk'])
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['nullable', 'integer'])
                ->examples(['1', '2'])
                ->exampleHeader('nama_induk'),
        ];
    }

    /**
